// RunPortableMigration is the resolver for the runPortableMigration field.
func (r *mutationResolver) RunPortableMigration(ctx context.Context, input PortableMigrationActionInput) (*PortableMigrationActionResult, error) {
	service, ok := r.Operations.(PortableOperationsService)
	if !ok {
		return nil, manageError(errors.New("portable migration operations are unavailable"))
	}
	if r.OwnerPassword == nil {
		return nil, manageError(errors.New("owner password verification is unavailable"))
	}
	if err := r.OwnerPassword.VerifyPassword(ctx, input.Password); err != nil {
		r.auditManage(ctx, "PORTABLE_MIGRATION_"+string(input.Action), "PORTABLE_MIGRATION", input.ImportID+input.MergeID, "OWNER_REAUTH_FAILED", err, nil)
		return nil, manageError(err)
	}
	request := PortableMigrationRequest{
		Action:                  string(input.Action),
		Path:                    input.Path,
		ImportID:                input.ImportID,
		MergeID:                 input.MergeID,
		Confirmation:            input.Confirmation,
		AllowIncompleteGallery:  input.AllowIncompleteGallery,
		IncludeGalleryLifecycle: input.IncludeGalleryLifecycle,
		IncludePersonalFlags:    input.IncludePersonalFlags,
	}
	for _, decision := range input.MergeDecisions {
		request.MergeDecisions = append(request.MergeDecisions, productdb.PortableMergeDecision{IssueKey: decision.IssueKey, Decision: decision.Decision})
	}
	for _, decision := range input.LibraryDecisions {
		request.LibraryDecisions = append(request.LibraryDecisions, productdb.PortableLibraryDecision{LibraryKey: decision.LibraryKey, TargetLibraryID: decision.TargetLibraryID})
	}
	value, err := service.RunPortableMigration(ctx, request)
	targetID := value.ImportID
	if targetID == "" {
		targetID = value.MergeID
	}
	r.auditManage(ctx, "PORTABLE_MIGRATION_"+string(input.Action), "PORTABLE_MIGRATION", targetID, "PORTABLE_MIGRATION_FAILED", err, map[string]any{"count": value.Count})
	if err != nil {
		return nil, errors.New("PORTABLE_" + string(input.Action) + "_FAILED")
	}
	return portableMigrationActionResult(value), nil
}

// CreateCoreEntity is the resolver for the createCoreEntity field.
func (r *mutationResolver) CreateCoreEntity(ctx context.Context, input CoreEntityInput) (*ManageCoreEntity, error) {
	if input.Kind != SearchEntityKindTag && (input.TagParentUUID != nil || input.ExpectedTagParentRevision != nil) {
		return nil, manageError(errors.New("Tag parent is only valid for Tag creation"))
	}
	if input.Kind == SearchEntityKindTag && (input.TagParentUUID == nil) != (input.ExpectedTagParentRevision == nil) {
		return nil, manageError(errors.New("Tag parent UUID and revision must be provided together"))
	}
	named := productdb.CreateNamedEntityInput{Name: input.Name, SortName: input.SortName, Aliases: input.Aliases}
	var uuid string
	var err error
	switch input.Kind {
	case SearchEntityKindCoser:
		var value coreentity.Coser
		value, err = r.Database.CoreEntities().CreateCoser(ctx, productdb.CreateCoserInput{CreateNamedEntityInput: named, ProfileSummary: input.ProfileSummary, Biography: input.Biography, CountryOrRegion: input.CountryOrRegion}, time.Now())
		uuid = value.UUID
	case SearchEntityKindWork:
		var value coreentity.Work
		value, err = r.Database.CoreEntities().CreateWork(ctx, named, time.Now())
		uuid = value.UUID
	case SearchEntityKindCharacter:
		if input.WorkUUID == nil {
			err = errors.New("Character requires a primary Work")
			r.auditManage(ctx, "CORE_ENTITY_CREATE", string(input.Kind), "new", "CORE_ENTITY_CREATE_FAILED", err, nil)
			return nil, err
		}
		var value coreentity.Character
		value, err = r.Database.CoreEntities().CreateCharacter(ctx, *input.WorkUUID, named, time.Now())
		uuid = value.UUID
	case SearchEntityKindTag:
		var value coreentity.Tag
		parentUUID := ""
		parentRevision := int64(0)
		if input.TagParentUUID != nil {
			parentUUID = *input.TagParentUUID
		}
		if input.ExpectedTagParentRevision != nil {
			parentRevision = *input.ExpectedTagParentRevision
		}
		value, err = r.Database.CoreEntities().CreateTag(ctx, productdb.CreateTagInput{CreateNamedEntityInput: named, UseInRecommendation: input.UseInRecommendation, AllowDirectAssignment: input.AllowDirectAssignment, ParentUUID: parentUUID, ExpectedParentRevision: parentRevision}, time.Now())
		uuid = value.UUID
	default:
		err = errors.New("unsupported core entity kind")
	}
	if err != nil {
		r.auditManage(ctx, "CORE_ENTITY_CREATE", string(input.Kind), "new", "CORE_ENTITY_CREATE_FAILED", err, nil)
		return nil, manageError(err)
	}
	value, err := r.Database.CoreEntities().ManageFind(ctx, string(input.Kind), uuid)
	if err != nil {
		r.auditManage(ctx, "CORE_ENTITY_CREATE", string(input.Kind), uuid, "CORE_ENTITY_CREATE_FAILED", err, nil)
		return nil, manageError(err)
	}
	r.auditManage(ctx, "CORE_ENTITY_CREATE", string(input.Kind), uuid, "", nil, nil)
	return manageCoreEntity(value), nil
}

// UpdateCoreEntity is the resolver for the updateCoreEntity field.
func (r *mutationResolver) UpdateCoreEntity(ctx context.Context, uuid string, expectedMetadataRevision int64, input CoreEntityInput) (*ManageCoreEntity, error) {
	if input.TagParentUUID != nil || input.ExpectedTagParentRevision != nil {
		return nil, manageError(errors.New("Tag parents must be changed using the parent relation mutation"))
	}
	named := productdb.UpdateNamedEntityInput{Name: input.Name, SortName: input.SortName, Aliases: input.Aliases}
	var err error
	auditEvent := "CORE_ENTITY_UPDATE"
	var auditSummary map[string]any
	switch input.Kind {
	case SearchEntityKindCoser:
		current, findErr := r.Database.CoreEntities().FindCoser(ctx, uuid)
		if findErr != nil {
			return nil, manageError(findErr)
		}
		_, err = r.Database.CoreEntities().UpdateCoser(ctx, uuid, expectedMetadataRevision, productdb.UpdateCoserInput{Name: input.Name, SortName: input.SortName, Aliases: input.Aliases, ProfileSummary: input.ProfileSummary, Biography: input.Biography, CountryOrRegion: input.CountryOrRegion, AvatarPath: current.AvatarPath, BannerPath: current.BannerPath, AvatarCrop: current.AvatarCrop, BannerFocalPoint: current.BannerFocalPoint}, time.Now())
	case SearchEntityKindWork:
		_, err = r.Database.CoreEntities().UpdateWork(ctx, uuid, expectedMetadataRevision, named, time.Now())
	case SearchEntityKindCharacter:
		current, findErr := r.Database.CoreEntities().ManageFind(ctx, "CHARACTER", uuid)
		if findErr != nil {
			return nil, manageError(findErr)
		}
		if input.WorkUUID == nil {
			return nil, manageError(errors.New("Character requires a primary Work"))
		}
		if *input.WorkUUID != current.WorkUUID {
			auditEvent = "CHARACTER_WORK_MOVE"
			auditSummary = map[string]any{"previous_work_uuid": current.WorkUUID, "target_work_uuid": *input.WorkUUID}
		}
		_, err = r.Database.CoreEntities().UpdateCharacter(ctx, uuid, *input.WorkUUID, expectedMetadataRevision, named, time.Now())
	case SearchEntityKindTag:
		_, err = r.Database.CoreEntities().UpdateTag(ctx, uuid, expectedMetadataRevision, productdb.UpdateTagInput{UpdateNamedEntityInput: named, UseInRecommendation: input.UseInRecommendation, AllowDirectAssignment: input.AllowDirectAssignment}, time.Now())
	default:
		return nil, manageError(errors.New("unsupported core entity kind"))
	}
	if err != nil {
		r.auditManage(ctx, auditEvent, string(input.Kind), uuid, auditEvent+"_FAILED", err, auditSummary)
		return nil, manageError(err)
	}
	value, err := r.Database.CoreEntities().ManageFind(ctx, string(input.Kind), uuid)
	if err != nil {
		r.auditManage(ctx, auditEvent, string(input.Kind), uuid, auditEvent+"_FAILED", err, auditSummary)
		return nil, manageError(err)
	}
	r.auditManage(ctx, auditEvent, string(input.Kind), uuid, "", nil, auditSummary)
	return manageCoreEntity(value), nil
}

